action.script:
"""NotchAny 音乐小组件数据源 / 控制脚本（Apple Music）。

事件（$NOTCH_WIDGET_EVENT）：
  refresh / trigger / notification-*  → 只读当前状态
  playpause | next | prev     → 控制后回读
  seek   payload {"position": 秒}
  volume payload {"volume": 0-100}
  launch → 启动 Music.app
输出：notch_result(widget={...}, notification={...})——widget 喂展开托盘的小组件，
notification 喂收起态刘海通知（时间轴载荷，App 本地推进歌词/进度）。
播放中上报载荷；未运行/停止/无授权上报 {"end": True} 结束通知。
"""

import base64
import json
import os
import re
import subprocess
import time

CACHE_DIR = os.path.expanduser("~/.notchany/cache/music-widget")
ART_PX = 240
ART_CACHE_KEEP = 40
# osascript 拿不到自动化授权时的各种报错特征（中英文系统都覆盖）
UNAUTH_MARKERS = ("-1743", "Not authorized", "未获得授权", "не авторизован", "-10004")
LRC_TAG = re.compile(r"\[(\d{1,3}):(\d{1,2})(?:[.:](\d{1,3}))?\]")

READ_SCRIPT = r"""
tell application "Music"
	set stateCode to "stopped"
	if player state is playing then
		set stateCode to "playing"
	else if player state is paused then
		set stateCode to "paused"
	end if
	set positionText to ""
	try
		set positionText to (player position as text)
	end try
	set volumeText to "0"
	try
		set volumeText to (sound volume as text)
	end try
	set titleText to ""
	set artistText to ""
	set albumText to ""
	set durationText to "0"
	set trackKey to ""
	set lyricsText to ""
	try
		set theTrack to current track
		set titleText to (name of theTrack as text)
		try
			set artistText to (artist of theTrack as text)
		end try
		try
			set albumText to (album of theTrack as text)
		end try
		try
			set durationText to (duration of theTrack as text)
		end try
		try
			set trackKey to (persistent ID of theTrack as text)
		end try
		try
			set lyricsText to (lyrics of theTrack as text)
		end try
	end try
	return stateCode & tab & positionText & tab & volumeText & tab & titleText & tab & artistText & tab & albumText & tab & durationText & tab & trackKey & tab & lyricsText
end tell
"""

ART_SCRIPT = r"""
tell application "Music"
	set artCount to 0
	try
		set artCount to (count of artworks of current track)
	end try
	if artCount is 0 then return "none"
	set artBytes to (raw data of artwork 1 of current track)
end tell
set outFile to (POSIX file "__DEST__")
set fileRef to (open for access outFile with write permission)
try
	set eof fileRef to 0
	write artBytes to fileRef
	close access fileRef
on error errText
	try
		close access fileRef
	end try
	error errText
end try
return "ok"
"""


# ---------------------------------------------------------------- 基础工具

def osa(source, timeout=10):
    """跑一段 AppleScript，返回 (rc, stdout, stderr)。"""
    try:
        proc = subprocess.run(
            ["osascript"], input=source, capture_output=True, text=True, timeout=timeout
        )
    except subprocess.TimeoutExpired:
        return 1, "", "osascript timeout"
    except FileNotFoundError:
        return 1, "", "osascript not found"
    return proc.returncode, proc.stdout.rstrip("\n"), proc.stderr.strip()


def is_unauthorized(stderr):
    return any(marker in stderr for marker in UNAUTH_MARKERS)


def music_running():
    try:
        return subprocess.run(["pgrep", "-x", "Music"], capture_output=True).returncode == 0
    except Exception:
        return False


def to_float(text, default=0.0):
    text = (text or "").strip().replace(",", ".")
    try:
        return float(text)
    except ValueError:
        return default


def to_int(text, default=0):
    return int(round(to_float(text, default)))


def env_flag(key, default=True):
    raw = os.environ.get(key)
    if raw is None or raw == "":
        return default
    return raw not in ("0", "false", "False")


# ---------------------------------------------------------------- 歌词

def parse_lyrics(raw):
    """内嵌歌词 → {"synced": bool, "lines": [{"t": 秒|None, "text": str}]}"""
    raw = (raw or "").strip()
    if not raw:
        return {"synced": False, "lines": []}

    timed, plain = [], []
    for line in raw.splitlines():
        tags = list(LRC_TAG.finditer(line))
        text = LRC_TAG.sub("", line).strip()
        if tags:
            for tag in tags:
                minutes = int(tag.group(1))
                seconds = int(tag.group(2))
                frac = float("0." + tag.group(3)) if tag.group(3) else 0.0
                timed.append({"t": round(minutes * 60 + seconds + frac, 3), "text": text})
        elif text:
            plain.append(text)

    if timed:
        timed.sort(key=lambda item: item["t"])
        return {"synced": True, "lines": timed[:400]}
    return {"synced": False, "lines": [{"t": None, "text": t} for t in plain[:400]]}


# ---------------------------------------------------------------- 封面

def prune_art_cache():
    try:
        entries = [
            os.path.join(CACHE_DIR, name)
            for name in os.listdir(CACHE_DIR)
            if name.startswith("art-")
        ]
    except OSError:
        return
    if len(entries) <= ART_CACHE_KEEP:
        return
    entries.sort(key=lambda p: os.path.getmtime(p))
    for path in entries[: len(entries) - ART_CACHE_KEEP]:
        try:
            os.remove(path)
        except OSError:
            pass


def artwork_data_uri(track_key):
    """提取当前曲目封面并降采样成 data URI；结果按 track_key 缓存。"""
    if not track_key:
        return ""

    safe_key = re.sub(r"[^A-Za-z0-9_-]", "_", track_key)[:64]
    cache_path = os.path.join(CACHE_DIR, "art-%s.txt" % safe_key)
    if os.path.exists(cache_path):
        try:
            with open(cache_path, "r", encoding="utf-8") as handle:
                cached = handle.read()
            os.utime(cache_path, None)
            return "" if cached == "none" else cached
        except OSError:
            pass

    temp_dir = os.environ.get("NOTCH_TEMP_DIR") or "/tmp"
    raw_path = os.path.join(temp_dir, "art-raw-%s.bin" % safe_key)
    jpg_path = os.path.join(temp_dir, "art-%s.jpg" % safe_key)

    rc, out, err = osa(ART_SCRIPT.replace("__DEST__", raw_path))
    if rc != 0 or out == "none" or not os.path.exists(raw_path):
        if rc == 0:  # 确认无封面才写 none，报错不缓存
            _write_cache(cache_path, "none")
        return ""

    try:
        conv = subprocess.run(
            ["sips", "-Z", str(ART_PX), "--setProperty", "format", "jpeg",
             raw_path, "--out", jpg_path],
            capture_output=True, timeout=15,
        )
        if conv.returncode != 0 or not os.path.exists(jpg_path):
            return ""
        with open(jpg_path, "rb") as handle:
            encoded = base64.b64encode(handle.read()).decode("ascii")
    except Exception:
        return ""

    uri = "data:image/jpeg;base64," + encoded
    _write_cache(cache_path, uri)
    prune_art_cache()
    return uri


def _write_cache(path, value):
    try:
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(value)
    except OSError:
        pass


# ---------------------------------------------------------------- 控制命令

def clamp(value, low, high):
    return max(low, min(high, value))


def run_command(event, payload):
    """执行控制命令。返回 (ok, err_stderr, 命令后建议的静置秒数)。"""
    if event == "playpause":
        rc, _, err = osa('tell application "Music" to playpause')
        return rc == 0, err, 0.25
    if event == "next":
        rc, _, err = osa('tell application "Music" to next track')
        return rc == 0, err, 0.45
    if event == "prev":
        # Music 沿用「播放超过约 2 秒时 previous track 只重播当前曲」的惯例。
        # 按钮写着「上一曲」就该真切上一首，所以先把进度归零再切。
        osa('tell application "Music" to set player position to 0')
        rc, _, err = osa('tell application "Music" to previous track')
        return rc == 0, err, 0.45
    if event == "seek":
        position = clamp(to_float(str(payload.get("position", 0))), 0.0, 86400.0)
        rc, _, err = osa('tell application "Music" to set player position to %.2f' % position)
        return rc == 0, err, 0.15
    if event == "volume":
        level = int(clamp(to_float(str(payload.get("volume", 50))), 0, 100))
        rc, _, err = osa('tell application "Music" to set sound volume to %d' % level)
        return rc == 0, err, 0.1
    return True, "", 0.0


# ---------------------------------------------------------------- 主流程

ACTIVATION_STATE_PATH = os.path.join(CACHE_DIR, "notification-activation.json")


def load_activation_state():
    try:
        with open(ACTIVATION_STATE_PATH, "r", encoding="utf-8") as handle:
            value = json.load(handle)
        return value if isinstance(value, dict) else {}
    except (OSError, ValueError):
        return {}


def save_activation_state(value):
    temp_path = ACTIVATION_STATE_PATH + ".tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(value, handle, ensure_ascii=False, sort_keys=True)
        os.chmod(temp_path, 0o600)
        os.replace(temp_path, ACTIVATION_STATE_PATH)
    except OSError:
        try:
            os.remove(temp_path)
        except OSError:
            pass


def mark_notification_inactive():
    previous = load_activation_state()
    if previous:
        previous["status"] = "inactive"
        save_activation_state(previous)


def end_notification():
    mark_notification_inactive()
    return {"end": "now-playing"}


def activation_id(state):
    track_id = state.get("trackId") or "unknown-track"
    status = state.get("status") or "paused"
    previous = load_activation_state()
    value = previous.get("activation_id")
    starts_new_activation = (
        not value
        or previous.get("track_id") != track_id
        or (status == "playing" and previous.get("status") != "playing")
    )
    if starts_new_activation:
        value = "music-%d" % time.time_ns()
    save_activation_state({
        "track_id": track_id,
        "status": status,
        "activation_id": value,
    })
    return value


def notification_payload(state, current_activation_id):
    art = state.get("art") or ""
    if art.startswith("data:image/jpeg;base64,"):
        icon = {"image_base64": art.split(",", 1)[1]}
    else:
        icon = {"symbol": "music.note"}
    payload = {
        "id": "now-playing",
        "type": "ongoing",
        "activation_id": current_activation_id,
        "icon": icon,
        "spin_period_seconds": 8,
        "title": state.get("title") or "",
        "details": state.get("artist") or "",
        "position_seconds": state.get("position") or 0,
        "paused": state.get("status") != "playing",
    }
    if state.get("duration"):
        payload["duration_seconds"] = state["duration"]
    lyrics = state.get("lyrics") or {}
    if lyrics.get("synced"):
        payload["lines"] = [
            {"at_seconds": line["t"], "text": line["text"]}
            for line in lyrics["lines"][:300] if line.get("text")
        ]
    return payload


def emit(payload, summary=None, notification=None):
    notch_result(summary=summary or payload.get("title") or "音乐", widget=payload, notification=notification)  # noqa: F821


def main():
    os.makedirs(CACHE_DIR, exist_ok=True)

    event = os.environ.get("NOTCH_WIDGET_EVENT", "") or "refresh"
    raw_payload = os.environ.get("NOTCH_WIDGET_PAYLOAD", "") or "{}"
    try:
        payload = json.loads(raw_payload)
        if not isinstance(payload, dict):
            payload = {}
    except ValueError:
        payload = {}

    show_lyrics = True

    if event == "launch":
        subprocess.run(["open", "-a", "Music"], capture_output=True)
        time.sleep(1.2)

    if not music_running():
        emit({"status": "not_running", "showLyrics": show_lyrics}, summary="Music 未运行",
             notification=end_notification())
        return

    # 控制命令先跑，再回读，保证组件拿到的是命令后的状态
    if event in ("playpause", "next", "prev", "seek", "volume"):
        ok, err, settle = run_command(event, payload)
        if not ok and is_unauthorized(err):
            emit({"status": "permission_required", "showLyrics": show_lyrics},
                 summary="需要自动化授权", notification=end_notification())
            return
        if settle:
            time.sleep(settle)

    read_started = time.time()
    rc, out, err = osa(READ_SCRIPT)
    if rc != 0:
        if is_unauthorized(err):
            emit({"status": "permission_required", "showLyrics": show_lyrics},
                 summary="需要自动化授权", notification=end_notification())
            return
        raise SystemExit("读取 Music 状态失败: %s" % (err or "unknown"))

    fields = out.split("\t", 8)
    while len(fields) < 9:
        fields.append("")
    (state_code, position_text, volume_text, title, artist,
     album, duration_text, track_key, lyrics_raw) = fields

    title = title.strip()
    if not title:
        emit({"status": "stopped", "volume": to_int(volume_text, 50),
              "showLyrics": show_lyrics}, summary="未在播放", notification=end_notification())
        return

    duration = to_float(duration_text)
    position = to_float(position_text)
    # 读完之后还做了封面/歌词处理，把这段耗时补回进度锚点
    art = artwork_data_uri(track_key)
    lyrics = parse_lyrics(lyrics_raw) if show_lyrics else {"synced": False, "lines": []}
    position = position + (time.time() - read_started)
    if duration > 0:
        position = clamp(position, 0.0, duration)

    state = {
        "status": state_code,
        "title": title,
        "artist": artist.strip(),
        "album": album.strip(),
        "duration": round(duration, 3),
        "position": round(position, 3),
        "volume": to_int(volume_text, 50),
        "trackId": track_key or (title + "|" + artist),
        "art": art,
        "lyrics": lyrics,
        "showLyrics": show_lyrics,
    }

    icon = "playing" if state_code == "playing" else "paused"
    mark = "▶" if state_code == "playing" else "⏸"
    summary = "%s %s%s" % (mark, title, (" — " + artist.strip()) if artist.strip() else "")
    notch_result(summary=summary, widget=state, icon=icon,
                 notification=notification_payload(state, activation_id(state)))  # noqa: F821


main()

