/* 离屏自测环境不推进 CSS transition，所以全组件不依赖 transition 表达终态，
   所有视觉变化都由 JS 直接写样式。 */
html, body {
  margin: 0;
  height: 100%;
  background: transparent;
  overflow: hidden;
  -webkit-user-select: none;
  user-select: none;
}

.card {
  position: relative;
  box-sizing: border-box;
  height: 100%;
  padding: 9px 10px 8px;
  border-radius: 13px;
  background: rgba(255, 255, 255, .09);
  color: #fff;
  font: 12px -apple-system, "PingFang SC", system-ui, sans-serif;
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: hidden;
}

/* 封面色调铺底，让卡片跟着专辑走 */
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 13px;
  background: var(--tint, transparent);
  opacity: .55;
  pointer-events: none;
}
.card > * { position: relative; }

/* ---------------------------------------------------------- 头部 */
.head {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 0;
}

.art {
  flex: 0 0 auto;
  width: 56px;
  height: 56px;
  border-radius: 8px;
  overflow: hidden;
  background: rgba(255, 255, 255, .13);
  box-shadow: 0 2px 8px rgba(0, 0, 0, .32);
  display: flex;
  align-items: center;
  justify-content: center;
}
.art-img { width: 100%; height: 100%; object-fit: cover; display: block; }
.art-ph { width: 26px; height: 26px; color: rgba(255, 255, 255, .42); }
.art-ph svg { width: 100%; height: 100%; display: block; }

.meta { min-width: 0; flex: 1 1 auto; }
.title {
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: .1px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.artist {
  margin-top: 2px;
  font-size: 10.5px;
  color: rgba(255, 255, 255, .6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.album {
  display: none;
  margin-top: 3px;
  font-size: 10px;
  color: rgba(255, 255, 255, .38);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 没歌词时不留空档：封面放大、补上专辑名，整块头部吃掉多余高度 */
.card.no-lyrics .lyrics { display: none; }
.card.no-lyrics .head { flex: 1 1 auto; }
.card.no-lyrics .art { width: 92px; height: 92px; border-radius: 10px; }
.card.no-lyrics .art-ph { width: 40px; height: 40px; }
.card.no-lyrics .title { font-size: 14.5px; -webkit-line-clamp: 3; }
.card.no-lyrics .artist { font-size: 11.5px; margin-top: 4px; }
.card.no-lyrics .album { display: block; }

/* ---------------------------------------------------------- 歌词 */
.lyrics {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  position: relative;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 22%, #000 78%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 22%, #000 78%, transparent);
}
.lyrics.empty { -webkit-mask-image: none; mask-image: none; }
/* .lyrics-col 是绝对定位，空态下 height:100% 会塌成 0，改回文档流才能居中 */
.lyrics.empty .lyrics-col { position: static; height: 100%; }

.lyrics-col {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  will-change: transform;
}
.lyric-line {
  font-size: 10.5px;
  line-height: 15px;
  height: 15px;
  color: rgba(255, 255, 255, .38);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}
.lyric-line.on {
  color: #fff;
  font-weight: 600;
  font-size: 11px;
}
.lyric-hint {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: rgba(255, 255, 255, .3);
}

/* ---------------------------------------------------------- 进度 */
.seekrow { display: flex; align-items: center; gap: 7px; }
.time {
  flex: 0 0 auto;
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  color: rgba(255, 255, 255, .5);
  letter-spacing: .2px;
}

.range {
  -webkit-appearance: none;
  appearance: none;
  flex: 1 1 auto;
  min-width: 0;
  height: 12px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}
.range::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 2px;
  background: var(--fill, rgba(255, 255, 255, .22));
}
.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 9px;
  height: 9px;
  margin-top: -3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(0, 0, 0, .45);
}
.range:disabled { cursor: default; opacity: .45; }
.range:disabled::-webkit-slider-thumb { background: rgba(255, 255, 255, .5); }

/* ---------------------------------------------------------- 控制 */
.ctlrow { display: flex; align-items: center; gap: 3px; }

.btn {
  -webkit-appearance: none;
  appearance: none;
  flex: 0 0 auto;
  width: 24px;
  height: 22px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, .88);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.btn svg { width: 15px; height: 15px; fill: currentColor; display: block; }
.btn.main svg { width: 17px; height: 17px; }
.btn:hover { background: rgba(255, 255, 255, .14); }
.btn:active { background: rgba(255, 255, 255, .2); }
.btn:disabled { color: rgba(255, 255, 255, .3); cursor: default; background: transparent; }

.volwrap {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 4px;
}
.volicon { flex: 0 0 auto; width: 12px; height: 12px; color: rgba(255, 255, 255, .55); }
.volicon svg { width: 100%; height: 100%; fill: currentColor; display: block; }
.volicon .wave1, .volicon .wave2 { opacity: 1; }
.vol { height: 12px; }

/* ---------------------------------------------------------- 覆盖态 */
.overlay {
  position: absolute;
  inset: 0;
  border-radius: 13px;
  background: rgba(18, 18, 20, .97);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  text-align: center;
  box-sizing: border-box;
}
.overlay[hidden] { display: none; }
.overlay-text {
  font-size: 10.5px;
  line-height: 1.5;
  color: rgba(255, 255, 255, .78);
  white-space: pre-line;   /* 文案里的 \n 要真的换行 */
}
.overlay-btn {
  -webkit-appearance: none;
  appearance: none;
  border: 0;
  border-radius: 7px;
  padding: 5px 12px;
  font: 600 10.5px -apple-system, "PingFang SC", system-ui, sans-serif;
  color: #fff;
  background: rgba(255, 255, 255, .18);
  cursor: pointer;
}
.overlay-btn[hidden] { display: none; }
.overlay-btn:hover { background: rgba(255, 255, 255, .26); }

