/* NotchAny 音乐小组件（Apple Music）
 *
 * 数据心法：脚本只在「换曲 / 播放态变化 / 5s 兜底」时跑，进度与歌词行由 JS 按墙钟
 * 本地推进（脚本回传 position 锚点 + 收到时刻），避免每秒调脚本。
 * 注意：离屏自测不推进 CSS transition，所以这里所有视觉终态都直接写样式，不靠过渡。
 */
(function () {
  'use strict';

  var SYNC_MS = 5000;   // 低频兜底重同步（换曲/播放态主要靠 playerInfo trigger 推）
  var TICK_MS = 100;    // 本地时间轴推进
  var LINE_H = 15;      // 与 .lyric-line 的 line-height 保持一致
  var QUIET_ERRORS = ['hidden', 'throttled', 'rate_limited', 'busy'];

  function $(id) { return document.getElementById(id); }
  var el = {
    card: $('card'), art: $('art'), artImg: $('artImg'), artPh: $('artPh'),
    title: $('title'), artist: $('artist'), album: $('album'),
    lyrics: $('lyrics'), lyricsCol: $('lyricsCol'),
    seek: $('seek'), time: $('time'),
    prev: $('prev'), playpause: $('playpause'), next: $('next'), ppIcon: $('ppIcon'),
    volume: $('volume'), volicon: $('volicon'),
    overlay: $('overlay'), overlayText: $('overlayText'), overlayBtn: $('overlayBtn')
  };

  var PLAY_PATH = '<path d="M7.6 4.9v14.2L20 12z"/>';
  var PAUSE_PATH = '<path d="M8 5h3.1v14H8zM12.9 5H16v14h-3.1z"/>';

  // 界面文案一律走词条：native 已按界面语言解析成单语字典，语言切换时会重建文档
  var I18N = (window.__notchWidget || {}).i18n || {};
  function t(k) { var v = I18N[k]; return v == null ? k : v; }

  var st = null;          // 最近一次脚本状态
  var baseWall = 0;       // 收到该状态的墙钟毫秒
  var tickTimer = null, syncTimer = null;
  var seeking = false, volAdjusting = false;
  var lyricNodes = [], lyricSig = '', activeIdx = -1;
  var artSig = '';
  var queue = [], running = false;

  // ------------------------------------------------------------ 工具

  function fmt(sec) {
    sec = Math.max(0, Math.floor(sec || 0));
    var m = Math.floor(sec / 60), s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function fillStyle(node, ratio) {
    var pct = Math.max(0, Math.min(1, ratio || 0)) * 100;
    node.style.setProperty(
      '--fill',
      'linear-gradient(to right, rgba(255,255,255,.92) ' + pct + '%, rgba(255,255,255,.22) ' + pct + '%)'
    );
  }

  function currentPosition() {
    if (!st) return 0;
    var p = st.position || 0;
    if (st.status === 'playing') p += (Date.now() - baseWall) / 1000;
    if (st.duration > 0) p = Math.min(p, st.duration);
    return Math.max(0, p);
  }

  // ------------------------------------------------------------ 调用队列

  function enqueue(event, payload, coalesce) {
    if (coalesce) {
      for (var i = 0; i < queue.length; i++) {
        if (queue[i].event === event) { queue[i].payload = payload; pump(); return; }
      }
    }
    if (queue.length >= 4) queue.shift();
    queue.push({ event: event, payload: payload });
    pump();
  }

  function pump() {
    if (running || !queue.length) return;
    running = true;
    var job = queue.shift();
    Promise.resolve(notchany.invoke(job.event, job.payload)).then(function (res) {
      applyResult(res);
    })['catch'](function (err) {
      console.error('invoke ' + job.event + ' 失败', err);
    }).then(function () {
      running = false;
      if (queue.length) pump();
    });
  }

  function refresh() { enqueue('refresh', null, true); }

  // ------------------------------------------------------------ 状态落地

  function applyResult(res) {
    if (!res) return;
    if (res.ok === false) {
      var code = (res.error && res.error.code) || '';
      if (QUIET_ERRORS.indexOf(code) < 0) {
        console.warn('刷新失败', code, res.error && res.error.message);
      }
      return;
    }
    var next = res.state || res;
    if (!next || typeof next !== 'object') return;
    st = next;
    baseWall = Date.now();
    render();
  }

  function render() {
    if (!st) return;

    if (st.status === 'not_running') {
      showOverlay(t('not_running'), t('open_music'), function () { enqueue('launch', null, true); });
      return;
    }
    if (st.status === 'permission_required') {
      showOverlay(t('perm_needed'), t('retry'), refresh);
      return;
    }
    hideOverlay();

    var hasTrack = !!st.title;
    el.title.textContent = hasTrack ? st.title : t('idle');
    el.artist.textContent = hasTrack ? (st.artist || '') : '';
    el.album.textContent = hasTrack ? (st.album || '') : '';

    renderArt(hasTrack ? (st.art || '') : '');
    renderLyrics();

    var playing = st.status === 'playing';
    el.ppIcon.innerHTML = playing ? PAUSE_PATH : PLAY_PATH;
    el.playpause.title = playing ? t('a11y_pause') : t('a11y_play');
    el.prev.disabled = !hasTrack;
    el.next.disabled = !hasTrack;

    var dur = st.duration || 0;
    el.seek.disabled = !(hasTrack && dur > 0);
    el.seek.max = dur > 0 ? dur : 1;

    if (!volAdjusting) {
      var vol = typeof st.volume === 'number' ? st.volume : 50;
      el.volume.value = vol;
      fillStyle(el.volume, vol / 100);
      renderVolIcon(vol);
    }

    tick();
  }

  function renderArt(uri) {
    if (artSig === uri) return;
    artSig = uri;
    if (!uri) {
      el.artImg.hidden = true;
      el.artImg.removeAttribute('src');
      el.artPh.hidden = false;
      el.card.style.setProperty('--tint', 'transparent');
      return;
    }
    el.artPh.hidden = true;
    el.artImg.hidden = false;
    el.artImg.onload = function () { computeTint(el.artImg); };
    el.artImg.onerror = function () {
      el.artImg.hidden = true;
      el.artPh.hidden = false;
    };
    el.artImg.src = uri;
  }

  function computeTint(img) {
    try {
      var canvas = document.createElement('canvas');
      canvas.width = 8; canvas.height = 8;
      var ctx = canvas.getContext('2d');
      if (!ctx) return;
      ctx.drawImage(img, 0, 0, 8, 8);
      var data = ctx.getImageData(0, 0, 8, 8).data;
      var r = 0, g = 0, b = 0, n = 0;
      for (var i = 0; i < data.length; i += 4) { r += data[i]; g += data[i + 1]; b += data[i + 2]; n++; }
      if (!n) return;
      r = Math.round(r / n); g = Math.round(g / n); b = Math.round(b / n);
      el.card.style.setProperty(
        '--tint',
        'linear-gradient(140deg, rgba(' + r + ',' + g + ',' + b + ',.62), rgba(' + r + ',' + g + ',' + b + ',.14))'
      );
    } catch (e) {
      /* 取色失败无所谓，卡片退回中性底色 */
    }
  }

  function renderVolIcon(vol) {
    var svg = el.volicon.firstElementChild;
    if (!svg) return;
    var w1 = svg.querySelector('.wave1'), w2 = svg.querySelector('.wave2');
    if (w1) w1.style.opacity = vol > 0 ? '1' : '0';
    if (w2) w2.style.opacity = vol >= 50 ? '1' : '0';
  }

  // ------------------------------------------------------------ 歌词

  function renderLyrics() {
    var lyr = (st && st.lyrics) || { synced: false, lines: [] };
    var lines = lyr.lines || [];
    // 无歌词时切到「大封面」版式，别在中间留一大片空白
    if (lines.length) el.card.classList.remove('no-lyrics');
    else el.card.classList.add('no-lyrics');

    var sig = (st.trackId || '') + '#' + lines.length + '#' + (lyr.synced ? 's' : 'p');
    if (sig === lyricSig) return;
    lyricSig = sig;
    activeIdx = -1;
    el.lyricsCol.innerHTML = '';
    lyricNodes = [];

    if (!lines.length) {
      el.lyrics.classList.add('empty');
      var hint = document.createElement('div');
      hint.className = 'lyric-hint';
      hint.textContent = st.showLyrics === false
        ? ''
        : (st.title ? t('no_lyrics') : '');
      el.lyricsCol.appendChild(hint);
      el.lyricsCol.style.transform = 'translateY(0px)';
      return;
    }

    el.lyrics.classList.remove('empty');
    var frag = document.createDocumentFragment();
    for (var i = 0; i < lines.length; i++) {
      var node = document.createElement('div');
      node.className = 'lyric-line';
      node.textContent = lines[i].text || '';
      frag.appendChild(node);
      lyricNodes.push(node);
    }
    el.lyricsCol.appendChild(frag);
  }

  function updateLyricScroll(pos) {
    if (!lyricNodes.length || !st) return;
    var lyr = st.lyrics || {};
    var lines = lyr.lines || [];
    var idx;

    if (lyr.synced) {
      idx = -1;
      for (var i = 0; i < lines.length; i++) {
        if (lines[i].t <= pos + 0.15) idx = i; else break;
      }
      if (idx < 0) idx = 0;
    } else {
      // 无时间轴：按播放进度线性带过整段歌词
      var ratio = st.duration > 0 ? pos / st.duration : 0;
      idx = Math.min(lines.length - 1, Math.max(0, Math.floor(ratio * lines.length)));
    }

    if (idx !== activeIdx) {
      if (lyricNodes[activeIdx]) lyricNodes[activeIdx].className = 'lyric-line';
      if (lyricNodes[idx]) lyricNodes[idx].className = 'lyric-line on';
      activeIdx = idx;
    }
    var center = Math.max(0, (el.lyrics.clientHeight - LINE_H) / 2);
    el.lyricsCol.style.transform = 'translateY(' + (center - idx * LINE_H) + 'px)';
  }

  // ------------------------------------------------------------ 每帧推进

  function tick() {
    if (!st || st.status === 'not_running' || st.status === 'permission_required') return;
    var pos = currentPosition();
    var dur = st.duration || 0;

    if (!seeking) {
      el.seek.value = dur > 0 ? Math.min(pos, dur) : 0;
      fillStyle(el.seek, dur > 0 ? pos / dur : 0);
    }
    el.time.textContent = fmt(seeking ? Number(el.seek.value) : pos) + ' / ' + fmt(dur);
    updateLyricScroll(pos);
  }

  // ------------------------------------------------------------ 覆盖态

  function showOverlay(text, btnLabel, onClick) {
    el.overlayText.textContent = text;
    if (btnLabel) {
      el.overlayBtn.hidden = false;
      el.overlayBtn.textContent = btnLabel;
      el.overlayBtn.onclick = onClick;
    } else {
      el.overlayBtn.hidden = true;
      el.overlayBtn.onclick = null;
    }
    el.overlay.hidden = false;
  }

  function hideOverlay() { el.overlay.hidden = true; }

  // ------------------------------------------------------------ 交互

  el.playpause.addEventListener('click', function () { enqueue('playpause', null, false); });
  el.prev.addEventListener('click', function () { enqueue('prev', null, false); });
  el.next.addEventListener('click', function () { enqueue('next', null, false); });

  el.seek.addEventListener('input', function () {
    seeking = true;
    var v = Number(el.seek.value) || 0;
    var dur = (st && st.duration) || 0;
    fillStyle(el.seek, dur > 0 ? v / dur : 0);
    el.time.textContent = fmt(v) + ' / ' + fmt(dur);
  });
  el.seek.addEventListener('change', function () {
    var v = Number(el.seek.value) || 0;
    seeking = false;
    if (st) { st.position = v; baseWall = Date.now(); }
    enqueue('seek', { position: v }, true);
  });

  el.volume.addEventListener('input', function () {
    volAdjusting = true;
    var v = Number(el.volume.value) || 0;
    fillStyle(el.volume, v / 100);
    renderVolIcon(v);
  });
  el.volume.addEventListener('change', function () {
    var v = Number(el.volume.value) || 0;
    volAdjusting = false;
    if (st) st.volume = v;
    enqueue('volume', { volume: v }, true);
  });

  // ------------------------------------------------------------ 生命周期

  function startTimers() {
    stopTimers();
    tickTimer = setInterval(tick, TICK_MS);
    syncTimer = setInterval(refresh, SYNC_MS);
  }

  function stopTimers() {
    if (tickTimer) { clearInterval(tickTimer); tickTimer = null; }
    if (syncTimer) { clearInterval(syncTimer); syncTimer = null; }
  }

  notchany.addEventListener('statechange', function () { applyResult(notchany.state); });

  notchany.addEventListener('visibilitychange', function () {
    if (notchany.visible) {
      refresh();      // triggers 用时也保留这句：重新可见的首帧靠它兜底
      startTimers();
    } else {
      stopTimers();
    }
  });

  // 静态文案：首帧状态到达前就要正确，所以挂载时先落一遍词条
  el.title.textContent = t('idle');
  el.seek.title = t('a11y_seek');
  el.prev.title = t('a11y_prev');
  el.playpause.title = t('a11y_playpause');
  el.next.title = t('a11y_next');
  el.volume.title = t('a11y_volume');

  // 若挂载时已可见（notchany.visible 初始为 false，这里只是保险）
  if (notchany.visible) { refresh(); startTimers(); }
  if (notchany.state) applyResult(notchany.state);
})();
